#nullable enable // autogenerated

using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Enemy
{
    [AutoBuffDefinition(VanillaBuffNames.Enemy.endlessGate)]
    public class EndlessGateBuff : BuffDefinition
    {
        public EndlessGateBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new ColorModifier(EngineEntityProps.COLOR_OFFSET, PROP_COLOR_OFFSET));
            AddModifier(new ColorModifier(EngineEntityProps.HELMET_COLOR_OFFSET, PROP_COLOR_OFFSET));
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            UpdateColorOffset(buff);
            buff.SetProperty(PROP_EFFECT_DURATION, 30);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            UpdateColorOffset(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;

            var duration = buff.GetProperty<int>(PROP_EFFECT_DURATION);
            duration--;
            buff.SetProperty(PROP_EFFECT_DURATION, duration);

            var pos = entity.Position;
            pos.x = pos.x * 0.8f + TLELPORT_X * 0.2f;
            entity.Position = pos;

            if (duration <= 0)
            {
                buff.Remove();
            }
        }
        private void UpdateColorOffset(Buff buff)
        {
            var time = buff.GetProperty<int>(PROP_TIME);
            time++;
            time %= MAX_TIME;
            var alpha = 1 - (Mathf.Cos((float)time / MAX_TIME * 360 * Mathf.Deg2Rad) + 1) / 2;
            alpha *= 0.8f;
            buff.SetProperty(PROP_COLOR_OFFSET, new Color(1, 1, 1, alpha));
            buff.SetProperty(PROP_TIME, time);
        }
        public const float TLELPORT_X = LevelPositions.RIGHT_BORDER;
        public const int MAX_TIME = 15;
        public static readonly VanillaBuffPropertyMeta<int> PROP_TIME = new VanillaBuffPropertyMeta<int>("Time");
        public static readonly VanillaBuffPropertyMeta<int> PROP_EFFECT_DURATION = new VanillaBuffPropertyMeta<int>("effect_duration");
        public static readonly VanillaBuffPropertyMeta<Color> PROP_COLOR_OFFSET = new VanillaBuffPropertyMeta<Color>("ColorOffset");
    }
}
